build(a, snap) {
    const nums = a.nums, N = {}, made = new Set(), pre = [];
    let root = null;
    const snapNodes = () => Object.fromEntries(Object.entries(N).map(([k, v]) => [k, { ...v }]));
    const view = (lo, hi, mid, opts = {}) => {
      const cls = {};
      for (const id in N) cls[id] = +id === mid ? "a" : "";
      const tree = root === null
        ? { t: "chips", label: "树", items: [], empty: "还没有节点" }
        : {
            t: "tree",
            label: "平衡二叉搜索树（带 L/R 方向）",
            nodes: snapNodes(),
            root,
            cls,
            directed: true,
            lrLabels: true,
            ptrs: mid >= 0 ? { node: mid } : {},
            ...(opts.prevNodes ? { prevNodes: opts.prevNodes } : {}),
            ...(opts.animEdges ? { animEdges: opts.animEdges } : {}),
            ...(opts.onEdges ? { onEdges: opts.onEdges } : {}),
          };
      const ptrs = lo <= hi ? (mid >= 0 ? { lo, mid, hi } : { lo, hi }) : {};
      return [
        { t: "array", label: "nums", items: nums.map((v, i) => ({ v, cls: i === mid ? "a" : made.has(i) ? "d" : i >= lo && i <= hi ? "e" : "" })), ptrs },
        tree,
      ];
    };
    let prevRange = `[0, ${nums.length - 1}]`, prevMid, prevCount = 0;
    snap("开始", "数组是有序的。先在整个数组里取中间的数当根。", view(0, nums.length - 1, -1), {
      at: "init",
      facts: [["区间 [lo, hi]", prevRange], ["已建节点", 0]],
    });
    const build = (lo, hi, parent, side) => {
      if (lo > hi) return null;
      const mid = (lo + hi) >> 1;
      const prevSnap = snapNodes();
      N[mid] = { v: nums[mid], l: null, r: null };
      made.add(mid);
      pre.push(nums[mid]);
      if (parent === null) root = mid;
      else N[parent][side] = mid;
      const rangeStr = `[${lo}, ${hi}]`, midStr = `${mid} (值 ${nums[mid]})`, curCount = made.size;
      const facts = [
        ["区间 [lo, hi]", rangeStr, prevRange],
        ["中点 mid", midStr, prevMid],
        ["已建节点", curCount, prevCount],
      ];
      prevRange = rangeStr;
      prevMid = midStr;
      prevCount = curCount;
      snap(
        "取中点建节点",
        `在下标 [${lo}, ${hi}] 这一段里，中点是下标 ${mid}，值 <b>${nums[mid]}</b>。` +
          (parent === null ? "它是整棵树的根。" : `它成为 ${nums[parent]} 的${side === "l" ? "左" : "右"}孩子。`) +
          (lo === hi ? "这一段只有它一个，是叶子。" : `它左边的 [${lo}, ${mid - 1}] 去建左子树，右边的 [${mid + 1}, ${hi}] 去建右子树。`),
        view(lo, hi, mid, {
          prevNodes: prevSnap,
          ...(parent !== null ? { animEdges: [[parent, mid]], onEdges: [[parent, mid]] } : {}),
        }),
        { at: lo === hi ? "node" : ["node", "sub"], facts },
      );
      build(lo, mid - 1, mid, "l");
      build(mid + 1, hi, mid, "r");
      return mid;
    };
    build(0, nums.length - 1, null, null);
    snap("完成", "每个数都成了一个节点。任何节点的左右子树高度最多差 1，中序遍历出来就是原数组。", view(0, -1, -1), {
      at: "done",
      kind: "ok",
      ans: pre,
      facts: [["区间 [lo, hi]", "空", prevRange], ["已建节点", made.size]],
    });
  }

